initial_condition:
with {
   the SUT containing an initial state
}

test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Batch Merge Entities with Response Status Code set to 207     and
        Batch Merge Entities with Response body containing batch operation result set to '${expected_batch_operation_result}'     and
        Query Entities with Updated Entities set to '${merged_entities}' valid entities
}

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/entityOperations/merge'
        method set to 'POST'
        Request batch merge operation over entity from entities_to_be_merged '@{entities_to_be_merged}' with Content-Type set to 'application/ld+json'
}
